function allowed_resource(PDO $db,array $u,string $type,int $id,bool $manage=false):bool{if($u['role']==='super_admin')return true;$c=$manage?'can_manage':'can_view';$s=$db->prepare("SELECT 1 FROM resource_permissions WHERE reseller_id=? AND resource_type=? AND resource_id=? AND can_view=1 AND {$c}=1");$s->execute([$u['id'],$type,$id]);return (bool)$s->fetchColumn();}
function h(string $s):string{return e($s);}

/* Minimal RouterOS API client; no Composer required. */
final class RouterOS{
 private $fp; private string $host; private int $port; private string $user; private string $pass;
 function __construct(array $r){$this->host=$r['host'];$this->port=(int)$r['api_port'];$this->user=$r['username'];$this->pass=dec_secret($r['password_enc']);}
 private function len(int $l):string{if($l<0x80)return chr($l);if($l<0x4000)return chr(($l>>8)|0x80).chr($l&255);if($l<0x200000)return chr(($l>>16)|0xC0).chr(($l>>8)&255).chr($l&255);if($l<0x10000000)return chr(($l>>24)|0xE0).chr(($l>>16)&255).chr(($l>>8)&255).chr($l&255);return chr(0xF0).pack('N',$l);}
 private function word(string $s):void{fwrite($this->fp,$this->len(strlen($s)).$s);}
 private function sentence(array $words):void{foreach($words as $w)$this->word($w);fwrite($this->fp,"\0");}
 private function readWord():?string{$c=fread($this->fp,1);if($c===false||$c==='')return null;$n=ord($c);if($n<128)$l=$n;elseif(($n&0xE0)===0xC0)$l=(($n&31)<<8)|ord(fread($this->fp,1));elseif(($n&0xF0)===0xE0)$l=(($n&15)<<16)|(ord(fread($this->fp,1))<<8)|ord(fread($this->fp,1));elseif(($n&0xF8)===0xF0)$l=(($n&7)<<24)|(ord(fread($this->fp,1))<<16)|(ord(fread($this->fp,1))<<8)|ord(fread($this->fp,1));else{$l=unpack('N',fread($this->fp,4))[1];}$s='';while(strlen($s)<$l){$x=fread($this->fp,$l-strlen($s));if($x===false||$x==='')break;$s.=$x;}return $s;}
 private function connect():void{$this->fp=@fsockopen($this->host,$this->port,$eno,$estr,8);if(!$this->fp)throw new RuntimeException("RouterOS connection failed: {$estr}");stream_set_timeout($this->fp,8);$this->sentence(['/login','=name='.$this->user,'=password='.$this->pass]);$r=$this->readSentence();if(isset($r['!trap']))throw new RuntimeException('RouterOS login rejected');}
 private function readSentence():array{$out=[];$type='';while(true){$w=$this->readWord();if($w===null||$w==='')break;if($w[0]==='!'){$type=$w;$out[$type]=$out[$type]??[];continue;}if($type)$out[$type][]=$w;}return $out;}
 function call(string $cmd,array $args=[]):array{$this->connect();$w=[$cmd];foreach($args as $k=>$v){$w[]='='.$k.'='.$v;}$this->sentence($w);$rows=[];while(true){$r=$this->readSentence();if(isset($r['!re']))$rows[]=$r['!re'];if(isset($r['!done']))break;if(isset($r['!trap'])){fclose($this->fp);throw new RuntimeException(implode(' ',array_map(fn($x)=>substr($x,5),$r['!trap'])));}}fclose($this->fp);$out=[];foreach($rows as $row){$a=[];foreach($row as $x){if(str_starts_with($x,'=')){[$k,$v]=array_pad(explode('=',substr($x,1),2),2,'');$a[$k]=$v;}}$out[]=$a;}return $out;}
}
function router(PDO $db,int $id):array{$s=$db->prepare('SELECT * FROM mikrotiks WHERE id=? AND active=1');$s->execute([$id]);$r=$s->fetch();if(!$r)throw new RuntimeException('MikroTik not found');return $r;}
function olt(PDO $db,int $id):array{$s=$db->prepare('SELECT * FROM olts WHERE id=? AND active=1');$s->execute([$id]);$r=$s->fetch();if(!$r)throw new RuntimeException('OLT not found');return $r;}
function run_olt(array $o,string $command,string $needle=''):string{
 $cmd=trim($command);if($cmd==='')throw new RuntimeException('OLT command is not configured.');
 /* Uses the hosting account's OpenSSH client with key-based authentication. For password-only ECOM devices, install phpseclib in vendor/ and replace this adapter. */
 $host=preg_replace('/[^a-zA-Z0-9.:-]/','',$o['host']);$port=(int)$o['port'];$u=preg_replace('/[^a-zA-Z0-9_.-]/','',$o['username']);
 $full='ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=8 -p '.escapeshellarg((string)$port).' '.escapeshellarg($u.'@'.$host).' '.escapeshellarg($cmd).' 2>&1';
 $out=shell_exec($full);if($out===null||stripos($out,'permission denied')!==false||stripos($out,'connection refused')!==false)throw new RuntimeException('OLT SSH command failed: '.trim((string)$out));return trim((string)$out);
}

