  elseif($action==='secret_action'){if($u['role']==='reseller'&&!allowed_resource($pdo,$u,'mikrotik',(int)$_POST['router_id'],true))throw new RuntimeException('No permission for this router.');$r=router($pdo,(int)$_POST['router_id']);$api=new RouterOS($r);$cmd=$_POST['cmd'];if(!in_array($cmd,['enable','disable','remove'],true))throw new RuntimeException('Invalid action.');$api->call('/ppp/secret/'.$cmd,['.id'=>$_POST['rid']]);audit($pdo,$u['id'],$cmd.'_pppoe_secret','mikrotik',$r['id'],$_POST['rid']);}
